def format_proposal_html(title: str, sections: dict):
    html = f'<!DOCTYPE html><html><head><title>{title}</title><style>body{{font-family: Arial, sans-serif; margin: 40px;}}h1{{color: #2c3e50;}}h2{{color: #34495e; border-bottom: 2px solid #3498db; padding-bottom: 10px;}}table{{border-collapse: collapse; width: 100%; margin: 20px 0;}}th, td{{border: 1px solid #ddd; padding: 12px; text-align: left;}}th{{background-color: #3498db; color: white;}}.summary{{background-color: #ecf0f1; padding: 20px; margin: 20px 0;}}</style></head><body><h1>{title}</h1>'
    for section_name, section_content in sections.items():
        html += f'<h2>{section_name}</h2><div>{section_content}</div>'
    html += '</body></html>'
    return html
